UPDATE questions SET
  choices = $EXPL$["Both the receivable and the payable are reported separately on the consolidated balance sheet","They are eliminated because the consolidated entity cannot owe money to itself","Only the parent''s receivable is reported; the subsidiary''s payable is removed","Only the subsidiary''s payable is reported; the parent''s receivable is removed"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (B): Under ASC 810-10-45-1, intercompany loan balances between a parent and consolidated subsidiary must be fully eliminated because the consolidated entity cannot hold a receivable from or payable to itself. This elimination applies to both principal balances and related intercompany interest.
Wrong (A): Reporting both balances would overstate assets and liabilities on the consolidated balance sheet.
Wrong (C): Selectively reporting only the receivable misrepresents the consolidated entity''s financial position.
